CREATE TABLE IF NOT EXISTS jurisdiction_evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction text NOT NULL, country_code text, evidence_type text NOT NULL, title text NOT NULL, issuing_authority text, source_url text, reference_number text, publication_date date, effective_date date, expiry_date date, source_reliability text NOT NULL DEFAULT 'Unassessed', verification_status text NOT NULL DEFAULT 'Unverified', evidence_summary text, document_url text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS legal_interpretations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), evidence_id uuid NOT NULL REFERENCES jurisdiction_evidence(id) ON DELETE CASCADE, interpretation_status text NOT NULL DEFAULT 'Pending Legal Review', interpretation text, reviewed_by text, reviewed_at timestamptz, caveat text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS regulatory_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), evidence_id uuid NOT NULL REFERENCES jurisdiction_evidence(id) ON DELETE CASCADE, jurisdiction text NOT NULL, action_required text NOT NULL, responsible_role text, priority text NOT NULL DEFAULT 'Medium', status text NOT NULL DEFAULT 'Open', due_date date, completion_date date, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS evidence_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), evidence_id uuid NOT NULL REFERENCES jurisdiction_evidence(id) ON DELETE CASCADE, review_type text NOT NULL, reviewer text, outcome text NOT NULL DEFAULT 'Pending', reviewed_at date, notes text, next_review_date date, created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO jurisdiction_evidence(jurisdiction,country_code,evidence_type,title,issuing_authority,source_reliability,verification_status,evidence_summary) SELECT 'Nigeria','NG','Foundational corporate record','Home jurisdiction profile — evidence register','ÒsánVault Africa governance office','Internal — requires source validation','Verified internally','Nigeria is the current home jurisdiction in the corporate architecture. Specific statutory requirements must be supported by primary Nigerian sources before operational reliance.' WHERE NOT EXISTS (SELECT 1 FROM jurisdiction_evidence WHERE title='Home jurisdiction profile — evidence register');
INSERT INTO regulatory_actions(evidence_id,jurisdiction,action_required,responsible_role,priority,status,notes) SELECT id,'Nigeria','Validate all corporate, tax, beneficial ownership, land, investment and sector requirements against current primary regulatory sources','General Counsel / Compliance Lead','High','Open','Evidence register must not substitute for jurisdiction-specific legal advice.' FROM jurisdiction_evidence WHERE title='Home jurisdiction profile — evidence register' AND NOT EXISTS (SELECT 1 FROM regulatory_actions WHERE action_required='Validate all corporate, tax, beneficial ownership, land, investment and sector requirements against current primary regulatory sources');